import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        // Rule: Create ONE scanner instance outside loops
        Scanner scanner = new Scanner(System.in);

        System.out.println("=== DEFENSIVE NUMBER PARSER ===");

        System.out.print("Please enter a positive integer: ");

        // Defensive check to avoid InputMismatchException
        if (scanner.hasNextInt()) {
            int number = scanner.nextInt();
            if (number > 0) {
                System.out.println("Success! You entered: " + number);
            } else {
                System.out.println("Notice: The number is not positive.");
            }
        } else {
            String badInput = scanner.next(); // Consume and discard bad token
            System.out.println("Error: '" + badInput + "' is not a valid integer.");
        }

        scanner.close(); // Close only at the very end of main
    }
}

