practiceProblems.solutionCode:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int num = scanner.nextInt();
        if (num < 0) {
            System.out.println("Error: Negative numbers not allowed");
        } else {
            System.out.println("Accepted: " + num);
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextDouble()) {
            double d = scanner.nextDouble();
            System.out.println("Valid double: " + d);
        } else {
            System.out.println("Error: Not a decimal number");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) {
            String bad = scanner.next();
            System.out.println("Discarded: " + bad);
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine().trim();
        int n = Integer.parseInt(line);
        System.out.println("Parsed: " + n);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        if (b == 0) {
            System.out.println("Error: Division by zero is undefined");
        } else {
            System.out.println("Result: " + (a / b));
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double price = scanner.nextDouble();
        if (price > 0.0) {
            System.out.printf("Price confirmed: Rs %.2f%n", price);
        } else {
            System.out.println("Error: Invalid price");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int day = scanner.nextInt();
        int month = scanner.nextInt();
        int year = scanner.nextInt();
        scanner.nextLine(); // clear buffer
        String holiday = scanner.nextLine();
        System.out.println("Holiday: " + holiday + " on " + day + "/" + month + "/" + year);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double score = scanner.nextDouble();
        if (score >= 0.0 && score <= 100.0) {
            System.out.println("Valid score: " + score + "%");
        } else {
            System.out.println("Error: Score out of range (0-100)");
        }
        scanner.close();
    }
}
